// Навигация по фрагментам молитвы и строки источника (#a5decf4a, #6a86f7e16f63). Только чтение.
import { expect, Page } from '@playwright/test';

/** Строка источника у фрагмента, утверждённого в админке: «מקור: … · אושר על ידי <имя>, <д.м.гггг>». */
export const APPROVED_LINE = /^מקור: .+אושר על ידי .+\d{1,2}\.\d{1,2}\.\d{4}/;
/** Строка у неутверждённого фрагмента. */
export const UNAPPROVED_LINE = /^הטקסט עדיין לא אושר/;
/** Любая из двух строк источника (GP-05: ровно одна на фрагмент). */
export const SOURCE_LINE = /^(הטקסט עדיין לא אושר|מקור: .+אושר על ידי )/;

export const counterLocator = (page: Page) => page.getByText(/^\d+ מתוך \d+$/).first();

async function readCounter(page: Page): Promise<[number, number] | null> {
  if ((await counterLocator(page).count()) === 0) return null;
  const m = (await counterLocator(page).innerText()).match(/(\d+) מתוך (\d+)/)!;
  return [Number(m[1]), Number(m[2])];
}

/** Позиция в молитве запоминается: «קודם» до «1 מתוך N», затем «המשך» до нужного номера. Возвращает N (1 — если счётчика нет). */
export async function openFragment(page: Page, key: string, target = 1): Promise<number> {
  await page.goto(`/prayer/${key}`);
  await expect(page.locator('#runner-section-info')).toBeVisible({ timeout: 20_000 });
  let c = await readCounter(page);
  if (!c) return 1;
  while (c[0] > 1) {
    await page.getByRole('button', { name: 'קודם', exact: true }).click();
    await expect(counterLocator(page)).toHaveText(`${c[0] - 1} מתוך ${c[1]}`);
    c = [c[0] - 1, c[1]];
  }
  while (c[0] < target) {
    await page.getByRole('button', { name: 'המשך', exact: true }).click();
    await expect(counterLocator(page)).toHaveText(`${c[0] + 1} מתוך ${c[1]}`);
    c = [c[0] + 1, c[1]];
  }
  return c[1];
}

/** Сохранить localStorage «prayer-progress» (позиции в молитвах) — вернуть через restoreProgress в finally. */
export async function saveProgress(page: Page): Promise<string | null> {
  await page.goto('/home');
  await expect(page.getByRole('button', { name: 'התחל תפילה' })).toBeVisible({ timeout: 20_000 });
  return page.evaluate(() => localStorage.getItem('prayer-progress'));
}

export async function restoreProgress(page: Page, saved: string | null) {
  await page.goto('/home');
  await page.evaluate((v) => {
    if (v === null) localStorage.removeItem('prayer-progress');
    else localStorage.setItem('prayer-progress', v);
  }, saved);
}
